<?php
namespace Pterodactyl\Http\Controllers\Admin;
use Illuminate\Http\Request; use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Schema; use Illuminate\Support\Str; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Nodexa\FlaxVpsClient;
class VpsHostingController extends Controller { public function index(){ $provider=Schema::hasTable('vps_providers')?DB::table('vps_providers')->first():null;$packages=Schema::hasColumn('billing_products','product_type')?DB::table('billing_products')->where('product_type','vps')->orderBy('sort_order')->get():collect();$services=Schema::hasTable('vps_services')?DB::table('vps_services')->orderByDesc('id')->limit(50)->get():collect();return view('admin.commerce.vps',compact('provider','packages','services'));} public function saveProvider(Request $r){$d=$r->validate(['endpoint'=>'required|url|max:255','api_key'=>'nullable|string|max:1000']);$old=DB::table('vps_providers')->first();$key=!empty($d['api_key'])?Crypt::encryptString($d['api_key']):($old->api_key??null);if(!$key)return back()->withErrors(['api_key'=>'API-nøgle er påkrævet første gang.']);$values=['name'=>'Flax Hosting','endpoint'=>rtrim($d['endpoint'],'/'),'api_key'=>$key,'active'=>true,'updated_at'=>now()];if($old)DB::table('vps_providers')->where('id',$old->id)->update($values);else DB::table('vps_providers')->insert($values+['created_at'=>now()]);return back()->with('success','Flax VPS API blev gemt sikkert.');} public function test(){try{$data=(new FlaxVpsClient())->servers();return back()->with('success','Forbindelsen til Flax virker. API returnerede '.count($data).' server(e).');}catch(\Throwable $e){return back()->withErrors(['flax'=>$e->getMessage()]);}} public function storePackage(Request $r){$d=$r->validate(['name'=>'required|string|max:120','description'=>'nullable|string|max:1000','provider_product_id'=>'required|string|max:100','default_os_id'=>'required|string|max:100','vcores'=>'nullable|integer|min:1|max:256','memory_mb'=>'required|integer|min:128','disk_mb'=>'required|integer|min:1024','price'=>'required|numeric|min:0','currency'=>'required|string|size:3']);$base=Str::slug($d['name'])?:'vps';$slug=$base;$i=2;while(DB::table('billing_products')->where('slug',$slug)->exists())$slug=$base.'-'.$i++;DB::table('billing_products')->insert(['name'=>$d['name'],'slug'=>$slug,'description'=>$d['description']??null,'product_type'=>'vps','provider_product_id'=>$d['provider_product_id'],'default_os_id'=>$d['default_os_id'],'vcores'=>$d['vcores']??null,'memory_mb'=>$d['memory_mb'],'disk_mb'=>$d['disk_mb'],'cpu_percent'=>null,'databases_limit'=>0,'backups_limit'=>0,'allocations_limit'=>1,'price'=>$d['price'],'currency'=>strtoupper($d['currency']),'billing_cycle'=>'monthly','active'=>true,'sort_order'=>0,'provisioning'=>json_encode(['type'=>'vps','provider'=>'flax','product_id'=>$d['provider_product_id'],'os_id'=>$d['default_os_id']]),'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','VPS-pakken blev oprettet og vises nu på VPS Hosting-siden.');} }
